      "gpu_profile",
      "secure_boot",
      "tpm_measurement",
      "attestation_assurance",
      "update_policy",
      "temporal_verification_profile_ref",
      "temporal_verification_profile_hash",
      "asserts_observed_measurement",
      "predecessor_boot_profile_root",
      "status",
      "created_at"
