      "steps",
      "rollback_steps",
      "gate_refs",
      "affected_refs",
      "maintenance_window_ref",
      "suppression_window_ref",
      "authority_scope_refs",
      "temporal_verification_profile_ref",
      "authority_currentness_floor_ref",
      "lifecycle_continuity_floor_ref",
      "ordering_finality_profile_ref",
      "activation",
      "restore"
