      "originating_daemon_or_provider_operation_ref",
      "environment_ref",
      "session_ref",
      "provider_ref",
      "resource_refs",
      "required_disposition",
      "cause",
      "reclaim_policy_ref",
      "required_authority_refs",
      "lifecycle_head_ref",
      "status",
      "escalation",
