      "approval_decision_root",
      "irreversibility",
      "required_scope",
      "operation_commitment",
      "input_hash",
      "policy_hash",
      "effect_hash",
      "authority_grant_ref",
      "authority_evidence_ref",
      "authority_evidence_root",
